    input[type="text"]:disabled,
    input[type="email"]:disabled,
    input[type="tel"]:disabled {
      background: #0f172a;
      opacity: 0.6;
      cursor: not-allowed;
    }

    input[aria-invalid="true"],
    input[aria-invalid="true"]:focus {
      border-color: #f87171;
      box-shadow: 0 0 0 3px rgba(248, 113, 113, 0.1);
    }

    .form-field-help {
      font-size: 12px;
      color: #94a3b8;
      margin-top: 6px;
      display: block;
    }

    .form-field-error {
      font-size: 12px;
      color: #fca5a5;
      margin-top: 6px;
      display: none;
    }

    .form-field-error.visible {
      display: block;
    }

    button[type="submit"] {
      padding: 12px 24px;
      font-size: 16px;
      font-weight: 600;
      border: none;
      border-radius: 6px;
      background: #3b82f6;
      color: white;
      cursor: pointer;
      transition: all 0.2s ease;
      font-family: inherit;
    }

    button[type="submit"]:hover {
      background: #2563eb;
    }

    button[type="submit"]:active {
      background: #1d4ed8;
    }

    button[type="submit"]:focus {
      outline: none;
      box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.5);
