  <main>
    <div class="container">
      <h1>Contact Us</h1>
      <p class="page-subtitle">We'd love to hear from you. Get in touch with our support team.</p>

      <form id="contactForm" novalidate>
        <div class="form-success" id="successMessage" role="status" aria-live="polite">
          Thank you! We've received your message and will get back to you soon.
        </div>

        <div class="form-field">
          <label for="fullName">
            Full Name
            <span class="required-marker" aria-hidden="true">*</span>
          </label>
          <input
            id="fullName"
            name="fullName"
            type="text"
            required
            autocomplete="name"
            aria-required="true"
            aria-describedby="fullName-error"
          >
          <span id="fullName-error" class="form-field-error"></span>
        </div>

        <div class="form-field">
          <label for="email">
            Email Address
            <span class="required-marker" aria-hidden="true">*</span>
          </label>
          <input
            id="email"
            name="email"
            type="email"
            required
            autocomplete="email"
            aria-required="true"
            aria-describedby="email-error"
          >
          <span id="email-error" class="form-field-error"></span>
        </div>

        <div class="form-field">
          <label for="phone">Phone Number</label>
          <input
            id="phone"
            name="phone"
            type="tel"
            autocomplete="tel"
            aria-describedby="phone-help phone-error"
          >
          <span id="phone-help" class="form-field-help">Format: +1 (555) 123-4567 or +44 20 7946 0958</span>
          <span id="phone-error" class="form-field-error"></span>
        </div>

        <button type="submit">Send Message</button>
      </form>
    </div>
  </main>

  <script>
    const form = document.getElementById('contactForm');
    const successMessage = document.getElementById('successMessage');

    const fieldConfig = {
      fullName: {
        validate: (value) => value.trim().length > 0,
        errorMessage: 'Error: Please enter your full name.'
      },
      email: {
        validate: (value) => {
          const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          return emailRegex.test(value.trim());
        },
        errorMessage: 'Error: Please enter a valid email address (e.g., your.name@example.com).'
      },
      phone: {
        validate: (value) => {
          if (value.trim().length === 0) return true;
          const phoneRegex = /^[\d+\s\-()]+$/;
          return phoneRegex.test(value.trim()) && value.trim().length >= 10;
        },
        errorMessage: 'Error: Please enter a valid phone number.'
      }
    };

    function clearFieldError(fieldName) {
      const input = document.getElementById(fieldName);
      const errorElement = document.getElementById(`${fieldName}-error`);

      input.removeAttribute('aria-invalid');
      errorElement.textContent = '';
      errorElement.classList.remove('visible');
    }

    function setFieldError(fieldName, message) {
      const input = document.getElementById(fieldName);
      const errorElement = document.getElementById(`${fieldName}-error`);

      input.setAttribute('aria-invalid', 'true');
      errorElement.textContent = message;
      errorElement.classList.add('visible');
    }

    function validateField(fieldName) {
      const config = fieldConfig[fieldName];
      const input = document.getElementById(fieldName);
      const value = input.value;

      if (!config.validate(value)) {
        setFieldError(fieldName, config.errorMessage);
        return false;
      }

      clearFieldError(fieldName);
      return true;
    }

    function validateForm() {
      let isValid = true;
      const fieldsToValidate = ['fullName', 'email', 'phone'];

      for (const fieldName of fieldsToValidate) {
        if (!validateField(fieldName)) {
          isValid = false;
        }
      }

      return isValid;
    }

    function focusFirstInvalidField() {
      const fieldsToCheck = ['fullName', 'email', 'phone'];

      for (const fieldName of fieldsToCheck) {
        const input = document.getElementById(fieldName);
        if (input.getAttribute('aria-invalid') === 'true') {
          input.focus();
          return;
        }
      }
    }

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      successMessage.classList.remove('visible');

      if (validateForm()) {
        successMessage.classList.add('visible');
        form.reset();
        form.style.display = 'none';
        setTimeout(() => {
          form.style.display = 'flex';
        }, 3000);
      } else {
        focusFirstInvalidField();
      }
    });

    document.getElementById('fullName').addEventListener('blur', () => {
      validateField('fullName');
    });

    document.getElementById('email').addEventListener('blur', () => {
      validateField('email');
    });

    document.getElementById('phone').addEventListener('blur', () => {
      validateField('phone');
    });
  </script>
</body>
</html>
