const fs = require('fs');
const path = require('path');
const axeSource = require('axe-core').source;

async function runAccessibilityTest() {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  const htmlPath = path.join(__dirname, 'index.html');
  const html = fs.readFileSync(htmlPath, 'utf-8');

  await page.setContent(html, { waitUntil: 'load' });

  // Inject and run axe
  await page.addScriptTag({ content: axeSource });
  const results = await page.evaluate(() => window.axe.run());

  await browser.close();

  // Separate WCAG violations from best-practice
  const wcagViolations = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bpViolations = results.violations.filter(v => v.tags.includes('best-practice'));

  console.log(JSON.stringify({
    wcag: wcagViolations.map(v => ({
      id: v.id,
      impact: v.impact,
      description: v.description,
      targets: v.nodes.map(n => n.target)
    })),
    bp: bpViolations.map(v => ({
      id: v.id,
      description: v.description,
      targets: v.nodes.map(n => n.target)
    }))
  }, null, 2));

  process.exit(wcagViolations.length > 0 ? 1 : 0);
}

runAccessibilityTest().catch(err => {
  console.error('Test error:', err.message);
  process.exit(1);
